// Prevent a console window on Windows release builds.
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

fn main() {
    fornax_lib::run();
}

// Core modules are declared at the crate root via `#[path]` so the ported
// code's existing `crate::message::…` / `crate::config::…` references keep
// working unchanged. The files physically live under `src/core/`.
#[path = "core/message.rs"]
pub mod message;
#[path = "core/api.rs"]
pub mod api;
#[path = "core/storage.rs"]
pub mod storage;
#[path = "core/config.rs"]
pub mod config;
#[path = "core/slash.rs"]
pub mod slash;
#[path = "core/markdown.rs"]
pub mod markdown;
#[path = "core/tools.rs"]
pub mod tools;
#[path = "core/agents.rs"]
pub mod agents;

mod commands;
mod mcp;
mod metrics;
mod state;

use state::AppState;
use tauri::Manager;

/// One-time move of pre-rename data from the legacy `hchat` directories to
/// `fornax`, so anyone upgrading keeps their conversations, config, and tools.
/// Runs before any path is read; no-ops once the `fornax` dirs exist.
fn migrate_legacy_dirs() {
    use std::fs;
    // config + tools live under config_dir; the SQLite db under data_dir.
    // (these are the same directory on macOS, distinct on Linux.)
    for base in [dirs::config_dir(), dirs::data_dir()].into_iter().flatten() {
        let old = base.join("hchat");
        let new = base.join("fornax");
        if new.exists() || !old.exists() {
            continue;
        }
        if fs::rename(&old, &new).is_ok() {
            // Rename the db file (+ its WAL/SHM sidecars) to match the new name.
            for ext in ["", "-wal", "-shm"] {
                let from = new.join(format!("hchat.db{ext}"));
                if from.exists() {
                    let _ = fs::rename(&from, new.join(format!("fornax.db{ext}")));
                }
            }
        }
    }
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    migrate_legacy_dirs();
    tauri::Builder::default()
        .manage(AppState::new())
        .setup(|app| {
            // Spawn the metrics poller + macmon thread; expose the active-target
            // handle so commands can retarget it.
            let target = metrics::start(app.handle().clone());
            app.manage(metrics::MetricsHandle(target));

            // Connect MCP servers in the background.
            let state = app.state::<AppState>();

            // Enforce the usage retention window once at startup.
            let retention = state.config.lock().unwrap().usage_retention_days;
            if retention > 0 {
                state.storage.lock().unwrap().prune_usage(retention);
            }

            let mcp = state.mcp.clone();
            let servers = state.config.lock().unwrap().mcp_servers.clone();
            if !servers.is_empty() {
                tauri::async_runtime::spawn(async move {
                    mcp.connect_all(servers).await;
                });
            }
            Ok(())
        })
        .invoke_handler(tauri::generate_handler![
            commands::get_config,
            commands::save_config,
            commands::fetch_models,
            commands::list_conversations,
            commands::load_conversation,
            commands::delete_conversation,
            commands::delete_all_conversations,
            commands::rename_conversation,
            commands::set_pinned,
            commands::usage_stats,
            commands::clear_usage,
            commands::run_benchmark,
            commands::list_projects,
            commands::create_project,
            commands::rename_project,
            commands::delete_project,
            commands::set_project_pinned,
            commands::set_conversation_project,
            commands::search_conversations,
            commands::export_conversation,
            commands::export_conversation_file,
            commands::save_draft,
            commands::list_agents,
            commands::list_mcp_servers,
            commands::reconnect_mcp,
            commands::cancel_stream,
            commands::send_message,
            commands::regenerate,
            commands::edit_message,
            commands::message_siblings,
            commands::walk_from,
            commands::resolve_tool,
            commands::list_presets,
            commands::create_preset,
            commands::delete_preset,
            commands::set_metrics_target,
        ])
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

use crate::config::Config;
use crate::mcp::McpManager;
use crate::storage::Storage;
use crate::tools;
use std::collections::{HashMap, HashSet};
use std::sync::{Arc, Mutex};
use tokio::sync::oneshot;
use tokio_util::sync::CancellationToken;

/// A parked tool-approval request: the oneshot to fulfill plus the context
/// needed to honor an "approve all in this conversation" decision.
pub struct PendingApproval {
    pub tx: oneshot::Sender<bool>,
    pub conversation_id: i64,
    pub tool: String,
}

/// All long-lived app state, managed by Tauri and shared across commands.
///
/// `Storage` wraps a rusqlite `Connection` (Send but not Sync), so it lives
/// behind a `Mutex`. Every command locks briefly for synchronous DB work and
/// drops the guard before any `.await` — never hold a lock across a suspend
/// point.
pub struct AppState {
    pub storage: Mutex<Storage>,
    pub config: Mutex<Config>,
    /// Cancellation tokens for in-flight chat streams, keyed by
    /// `conversation_id`. Each `run_turn` registers its token under its
    /// conversation; `cancel_stream(conversation_id)` fires (and removes) just
    /// that one, so streams in different chats run and cancel independently.
    pub cancel: Mutex<HashMap<i64, CancellationToken>>,
    /// Tool calls awaiting user approval, keyed by tool_call id. The streaming
    /// task parks a oneshot here and emits a `tool_approval` event; the
    /// `resolve_tool` command fulfills it with the user's decision.
    pub pending_approvals: Mutex<HashMap<String, PendingApproval>>,
    /// `(conversation_id, tool_name)` pairs the user chose to auto-approve for
    /// the rest of the session via "approve all in this conversation".
    pub auto_approved: Mutex<HashSet<(i64, String)>>,
    /// MCP client connections + discovered tools. Connected asynchronously after
    /// startup (see `lib.rs` setup).
    pub mcp: Arc<McpManager>,
}

impl AppState {
    pub fn new() -> Self {
        let config = Config::load();
        let storage = Storage::new();
        // Seed the default tools on first launch; tools are then (re)loaded from
        // disk on every turn, so edits take effect without a restart.
        tools::seed_defaults_if_empty(&tools::user_tools_dir());
        Self {
            storage: Mutex::new(storage),
            config: Mutex::new(config),
            cancel: Mutex::new(HashMap::new()),
            pending_approvals: Mutex::new(HashMap::new()),
            auto_approved: Mutex::new(HashSet::new()),
            mcp: McpManager::new(),
        }
    }

    /// Resolve the API key configured for `endpoint` (exact URL match against
    /// `saved_endpoints`). Returns `None` when the endpoint isn't saved or has
    /// no key — local servers (oMLX, llama.cpp) typically need none.
    pub fn api_key_for(&self, endpoint: &str) -> Option<String> {
        let cfg = self.config.lock().unwrap();
        cfg.saved_endpoints
            .iter()
            .find(|e| e.url == endpoint)
            .and_then(|e| e.api_key.clone())
    }
}

//! Tauri command layer. Replaces the egui `app.rs` orchestration: each command
//! locks `AppState` briefly for synchronous DB/config work and drops the guard
//! before any `.await`. Streaming chat forwards `StreamEvent`s from the core
//! `api::stream_chat` onto a frontend `Channel<ChatEvent>`.

use crate::api::{self, ChatParams, StreamEvent};
use crate::config::Config;
use crate::message::{ContentPart, ImageUrl, Message, Role, ToolCall};
use crate::state::AppState;
use crate::storage::ConversationSettings;
use crate::tools::{self, Handler, Safety, ToolDef};
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use std::sync::Arc;
use std::time::Instant;
use tauri::State;
use tauri::ipc::Channel;
use tokio::sync::{Semaphore, mpsc, oneshot};
use tokio_util::sync::CancellationToken;

/// Max tool-call → re-stream cycles per user turn (matches the egui app).
const MAX_TOOL_ITERATIONS: usize = 8;

// ---------- DTOs ----------

#[derive(Serialize)]
pub struct ConversationDto {
    pub id: i64,
    pub title: String,
    pub pinned: bool,
    pub project_id: Option<i64>,
    /// Short runtime code of the conversation's endpoint (omlx/llamaswap/…),
    /// for the sidebar backend icon.
    pub runtime: Option<String>,
}

#[derive(Serialize)]
pub struct ProjectDto {
    pub id: i64,
    pub name: String,
    pub pinned: bool,
}

#[derive(Serialize)]
pub struct UsageStatsDto {
    pub total_requests: i64,
    pub ok_requests: i64,
    pub prompt_tokens: i64,
    pub completion_tokens: i64,
    pub total_tokens: i64,
    pub total_cost: f64,
    pub ttft_p50_ms: Option<f64>,
    pub ttft_p95_ms: Option<f64>,
    pub decode_p50_tok_s: Option<f64>,
    pub decode_p95_tok_s: Option<f64>,
    pub by_model: Vec<UsageByModelDto>,
    pub daily: Vec<UsageDailyDto>,
}

#[derive(Serialize)]
pub struct UsageByModelDto {
    pub model: String,
    pub endpoint: String,
    pub requests: i64,
    pub prompt_tokens: i64,
    pub completion_tokens: i64,
    pub total_tokens: i64,
    pub cost: f64,
    pub avg_ttft_ms: Option<f64>,
    pub avg_decode_tok_s: Option<f64>,
}

#[derive(Serialize)]
pub struct UsageDailyDto {
    pub date: String,
    pub total_tokens: i64,
}

#[derive(Deserialize)]
pub struct BenchParams {
    pub endpoint: String,
    pub model: String,
    pub prompt: String,
    pub max_tokens: u32,
    pub concurrency: u32,
    pub total_requests: u32,
}

/// avg / p50 / p95 of a metric across the benchmark's successful requests.
#[derive(Serialize, Default)]
pub struct BenchAgg {
    pub avg: Option<f64>,
    pub p50: Option<f64>,
    pub p95: Option<f64>,
}

#[derive(Serialize)]
pub struct BenchResult {
    pub requests: u32,
    pub ok: u32,
    pub errors: u32,
    pub wall_ms: f64,
    pub ttft_ms: BenchAgg,
    pub decode_tok_s: BenchAgg,
    /// Aggregate decode throughput: completion tokens across all successful
    /// requests divided by wall-clock time (the headline concurrency number).
    pub agg_decode_tok_s: f64,
    pub total_completion_tokens: u64,
    /// Per-request points (successful only), in completion order, for charts.
    pub ttft_series: Vec<f64>,
    pub decode_series: Vec<f64>,
}

#[derive(Serialize)]
pub struct ToolCallDto {
    pub id: String,
    pub name: String,
    pub arguments: String,
}

#[derive(Serialize)]
pub struct MessageDto {
    pub id: Option<i64>,
    pub role: String,
    /// Concatenated text content (may contain `<think>` reasoning blocks and
    /// fenced code — the frontend segments + renders it).
    pub text: String,
    /// Data/HTTP image URLs attached to this message, in order.
    pub images: Vec<String>,
    pub tool_calls: Option<Vec<ToolCallDto>>,
    pub tool_call_id: Option<String>,
    /// Unix epoch ms (session-local for live messages, persisted for loaded ones).
    pub created_at: Option<i64>,
}

#[derive(Serialize)]
pub struct ConversationData {
    pub messages: Vec<MessageDto>,
    pub settings: SettingsDto,
    pub draft: Option<String>,
    /// Persisted compaction summary, if this conversation has been compacted.
    pub summary: Option<String>,
    /// The message id the summary covers up to (inclusive); the divider renders
    /// after this message.
    pub summary_through: Option<i64>,
}

/// Effective per-conversation settings (conversation overrides folded over the
/// global config defaults), ready for the UI to display as concrete values.
#[derive(Serialize)]
pub struct SettingsDto {
    pub model: Option<String>,
    pub endpoint: String,
    pub system_prompt: String,
    pub temperature: f32,
    pub max_tokens: u32,
    pub use_max_tokens: bool,
    pub top_p: Option<f32>,
    pub frequency_penalty: Option<f32>,
    pub presence_penalty: Option<f32>,
    pub stop_sequences: Vec<String>,
    pub working_dir: Option<String>,
    /// Effective auto-compaction settings (per-conversation override folded over
    /// the global config default).
    pub auto_compact: bool,
    pub compact_threshold_pct: f32,
    pub compact_keep_recent: u32,
}

/// Model + endpoint + sampling knobs shared by send/regenerate/edit. The API
/// key is *not* here — it's resolved server-side from `config.saved_endpoints`
/// so secrets never round-trip through JS. Flattened into the request structs
/// so the JS payload stays a single flat object.
#[derive(Deserialize, Clone)]
pub struct GenParams {
    pub endpoint: String,
    pub model: String,
    pub system_prompt: String,
    pub temperature: Option<f32>,
    pub max_tokens: Option<u32>,
    pub use_max_tokens: bool,
    pub top_p: Option<f32>,
    pub frequency_penalty: Option<f32>,
    pub presence_penalty: Option<f32>,
    #[serde(default)]
    pub stop_sequences: Vec<String>,
    /// Effective auto-compaction settings, already merged (global ← per-conversation)
    /// by the frontend. The backend looks up the endpoint's `context_window` itself.
    #[serde(default = "gp_default_true")]
    pub auto_compact: bool,
    #[serde(default)]
    pub compact_threshold_pct: f32,
    #[serde(default)]
    pub compact_keep_recent: u32,
}

fn gp_default_true() -> bool {
    true
}

#[derive(Deserialize)]
pub struct SendParams {
    pub conversation_id: Option<i64>,
    #[serde(flatten)]
    pub gp: GenParams,
    pub user_text: String,
    /// Image attachments as data/HTTP URLs, rendered into `image_url` content
    /// parts on the user message.
    #[serde(default)]
    pub images: Vec<String>,
}

#[derive(Deserialize)]
pub struct RegenerateParams {
    pub conversation_id: i64,
    #[serde(flatten)]
    pub gp: GenParams,
}

#[derive(Deserialize)]
pub struct EditParams {
    pub conversation_id: i64,
    pub message_id: i64,
    pub new_text: String,
    #[serde(flatten)]
    pub gp: GenParams,
}

/// Streaming events pushed to the frontend over the per-request `Channel`.
#[derive(Serialize, Clone)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ChatEvent {
    /// Conversation id, emitted first (covers the create-on-first-send case so
    /// the UI can adopt the new id immediately).
    Started { conversation_id: i64 },
    /// A new assistant turn is starting — the frontend pushes a fresh assistant
    /// placeholder. Emitted before the first turn and before each tool-driven
    /// continuation turn.
    TurnStart,
    Token { text: String },
    Reasoning { text: String },
    /// The model requested a tool call (attached to the current assistant
    /// message as a chip).
    ToolCall {
        id: String,
        name: String,
        arguments: String,
    },
    /// A Confirm-safety tool needs the user's go-ahead before it runs. The
    /// frontend shows an approval card and calls `resolve_tool`.
    ToolApproval {
        id: String,
        name: String,
        arguments: String,
    },
    /// A tool finished (or was denied) — the frontend appends a tool result
    /// bubble.
    ToolResult {
        id: String,
        name: String,
        result: String,
        is_error: bool,
    },
    Usage {
        prompt_tokens: Option<u32>,
        completion_tokens: Option<u32>,
        total_tokens: Option<u32>,
        cost: Option<f64>,
    },
    /// Per-request client-measured metrics (feed the Status dashboard tiles).
    RequestMetrics {
        ttft_ms: Option<f64>,
        decode_tok_s: Option<f64>,
        prefill_tok_s: Option<f64>,
        duration_ms: f64,
    },
    Done { message_id: Option<i64> },
    Error { message: String },
    /// Auto-compaction ran: older messages up to (and including) `through_id`
    /// were replaced by an LLM summary. The frontend renders a divider and stores
    /// the summary so it survives reload.
    Compacted {
        through_id: i64,
        summary: String,
        /// Number of messages folded into the summary.
        removed: usize,
    },
}

// ---------- helpers ----------

fn role_str(role: &Role) -> &'static str {
    match role {
        Role::System => "system",
        Role::User => "user",
        Role::Assistant => "assistant",
        Role::Tool => "tool",
    }
}

fn message_to_dto(m: &Message) -> MessageDto {
    let images = m
        .content
        .iter()
        .filter_map(|p| match p {
            ContentPart::ImageUrl { image_url } => Some(image_url.url.clone()),
            _ => None,
        })
        .collect();
    let tool_calls = m.tool_calls.as_ref().map(|calls| {
        calls
            .iter()
            .map(|c| ToolCallDto {
                id: c.id.clone(),
                name: c.function.name.clone(),
                arguments: c.function.arguments.clone(),
            })
            .collect()
    });
    MessageDto {
        id: m.id,
        role: role_str(&m.role).to_string(),
        text: m.text_str(),
        images,
        tool_calls,
        tool_call_id: m.tool_call_id.clone(),
        created_at: m.created_at,
    }
}

/// Fold conversation overrides over global config defaults.
fn effective_settings(cfg: &Config, cs: &ConversationSettings) -> SettingsDto {
    SettingsDto {
        model: cs.model.clone(),
        endpoint: cs.endpoint.clone().unwrap_or_else(|| cfg.default_endpoint.clone()),
        system_prompt: cs
            .system_prompt
            .clone()
            .unwrap_or_else(|| cfg.system_prompt.clone()),
        temperature: cs.temperature.unwrap_or(cfg.temperature),
        max_tokens: cs.max_tokens.unwrap_or(cfg.max_tokens),
        use_max_tokens: cs.use_max_tokens,
        top_p: cs.top_p.or(cfg.top_p),
        frequency_penalty: cs.frequency_penalty.or(cfg.frequency_penalty),
        presence_penalty: cs.presence_penalty.or(cfg.presence_penalty),
        stop_sequences: if cs.stop_sequences.is_empty() {
            cfg.stop_sequences.clone()
        } else {
            cs.stop_sequences.clone()
        },
        working_dir: cs.working_dir.clone(),
        auto_compact: cs.auto_compact.unwrap_or(cfg.auto_compact),
        compact_threshold_pct: cs
            .compact_threshold_pct
            .unwrap_or(cfg.compact_threshold_pct),
        compact_keep_recent: cs.compact_keep_recent.unwrap_or(cfg.compact_keep_recent),
    }
}

// ---------- config / models ----------

#[tauri::command]
pub fn get_config(state: State<'_, AppState>) -> Config {
    state.config.lock().unwrap().clone()
}

#[tauri::command]
pub fn save_config(state: State<'_, AppState>, mut config: Config) -> Result<(), String> {
    config.sanitize();
    config.save()?;
    *state.config.lock().unwrap() = config;
    Ok(())
}

#[tauri::command]
pub async fn fetch_models(
    state: State<'_, AppState>,
    endpoint: String,
) -> Result<Vec<api::ModelInfo>, String> {
    let api_key = state.api_key_for(&endpoint);
    api::fetch_models(&endpoint, api_key.as_deref()).await
}

// ---------- conversations ----------

fn runtime_code(r: crate::config::Runtime) -> &'static str {
    use crate::config::Runtime::*;
    match r {
        Vllm => "vllm",
        Omlx => "omlx",
        LlamaCpp => "llamacpp",
        LlamaSwap => "llamaswap",
        Openai => "openai",
    }
}

#[tauri::command]
pub fn list_conversations(state: State<'_, AppState>) -> Vec<ConversationDto> {
    let convs = state.storage.lock().unwrap().list_conversations();
    let cfg = state.config.lock().unwrap();
    convs
        .into_iter()
        .map(|c| {
            let runtime = c
                .endpoint
                .as_ref()
                .and_then(|ep| cfg.saved_endpoints.iter().find(|e| &e.url == ep))
                .map(|e| runtime_code(e.runtime).to_string());
            ConversationDto {
                id: c.id,
                title: c.title,
                pinned: c.pinned,
                project_id: c.project_id,
                runtime,
            }
        })
        .collect()
}

// ---------- usage ----------

#[tauri::command]
pub fn usage_stats(state: State<'_, AppState>) -> UsageStatsDto {
    let retention = state.config.lock().unwrap().usage_retention_days;
    let s = {
        let storage = state.storage.lock().unwrap();
        storage.prune_usage(retention);
        storage.usage_stats()
    };
    UsageStatsDto {
        total_requests: s.total_requests,
        ok_requests: s.ok_requests,
        prompt_tokens: s.prompt_tokens,
        completion_tokens: s.completion_tokens,
        total_tokens: s.total_tokens,
        total_cost: s.total_cost,
        ttft_p50_ms: s.ttft_p50_ms,
        ttft_p95_ms: s.ttft_p95_ms,
        decode_p50_tok_s: s.decode_p50_tok_s,
        decode_p95_tok_s: s.decode_p95_tok_s,
        by_model: s
            .by_model
            .into_iter()
            .map(|m| UsageByModelDto {
                model: m.model,
                endpoint: m.endpoint,
                requests: m.requests,
                prompt_tokens: m.prompt_tokens,
                completion_tokens: m.completion_tokens,
                total_tokens: m.total_tokens,
                cost: m.cost,
                avg_ttft_ms: m.avg_ttft_ms,
                avg_decode_tok_s: m.avg_decode_tok_s,
            })
            .collect(),
        daily: s
            .daily
            .into_iter()
            .map(|d| UsageDailyDto {
                date: d.date,
                total_tokens: d.total_tokens,
            })
            .collect(),
    }
}

#[tauri::command]
pub fn clear_usage(state: State<'_, AppState>) {
    state.storage.lock().unwrap().clear_usage();
}

// ---------- benchmark ----------

struct BenchSample {
    ttft_ms: Option<f64>,
    decode_tok_s: Option<f64>,
    completion: u32,
    ok: bool,
}

/// Nearest-rank percentile of a pre-sorted slice (`q` in 0.0..=1.0).
fn bench_percentile(sorted: &[f64], q: f64) -> Option<f64> {
    if sorted.is_empty() {
        return None;
    }
    let rank = (q * sorted.len() as f64).ceil() as usize;
    let idx = rank.saturating_sub(1).min(sorted.len() - 1);
    Some(sorted[idx])
}

fn bench_agg(vals: &[f64]) -> BenchAgg {
    if vals.is_empty() {
        return BenchAgg::default();
    }
    let avg = vals.iter().sum::<f64>() / vals.len() as f64;
    let mut sorted = vals.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    BenchAgg {
        avg: Some(avg),
        p50: bench_percentile(&sorted, 0.50),
        p95: bench_percentile(&sorted, 0.95),
    }
}

/// One benchmark request: stream a single completion and measure TTFT + decode.
async fn bench_once(
    endpoint: String,
    model: String,
    prompt: String,
    max_tokens: u32,
    api_key: Option<String>,
) -> BenchSample {
    let (tx, mut rx) = mpsc::unbounded_channel::<StreamEvent>();
    let params = ChatParams {
        base_url: endpoint,
        model,
        messages: vec![Message::text(Role::User, prompt)],
        temperature: None,
        max_tokens: Some(max_tokens),
        top_p: None,
        frequency_penalty: None,
        presence_penalty: None,
        stop_sequences: None,
        api_key,
        tools: None,
    };
    let start = Instant::now();
    api::stream_chat(params, tx, CancellationToken::new());

    let mut first_token: Option<Instant> = None;
    let mut completion: u32 = 0;
    let mut errored = false;
    while let Some(ev) = rx.recv().await {
        match ev {
            StreamEvent::Token(_) | StreamEvent::Reasoning(_) => {
                first_token.get_or_insert_with(Instant::now);
            }
            StreamEvent::UsageInfo(u) => {
                if let Some(c) = u.completion_tokens {
                    completion = c;
                }
            }
            StreamEvent::Error(_) => errored = true,
            StreamEvent::Done => break,
            _ => {}
        }
    }
    if errored {
        return BenchSample {
            ttft_ms: None,
            decode_tok_s: None,
            completion: 0,
            ok: false,
        };
    }
    let now = Instant::now();
    let ttft_ms = first_token.map(|f| f.duration_since(start).as_secs_f64() * 1000.0);
    let decode_tok_s = match first_token {
        Some(f) if completion > 0 => {
            let secs = now.duration_since(f).as_secs_f64();
            (secs > 0.0).then(|| completion as f64 / secs)
        }
        _ => None,
    };
    BenchSample {
        ttft_ms,
        decode_tok_s,
        completion,
        ok: true,
    }
}

/// Fire `total_requests` completions at an endpoint (≤ `concurrency` in flight)
/// and report TTFT/decode percentiles plus aggregate throughput.
#[tauri::command]
pub async fn run_benchmark(
    state: State<'_, AppState>,
    params: BenchParams,
) -> Result<BenchResult, String> {
    if params.model.trim().is_empty() {
        return Err("Pick a model to benchmark.".into());
    }
    let concurrency = params.concurrency.clamp(1, 64) as usize;
    let total = params.total_requests.clamp(1, 500);
    let max_tokens = params.max_tokens.clamp(1, 4096);
    let prompt = if params.prompt.trim().is_empty() {
        "Write a few sentences about the history of computing.".to_string()
    } else {
        params.prompt.clone()
    };
    let api_key = state.api_key_for(&params.endpoint);

    let sem = Arc::new(Semaphore::new(concurrency));
    let mut handles = Vec::with_capacity(total as usize);
    let wall_start = Instant::now();
    for _ in 0..total {
        let permit_src = sem.clone();
        let endpoint = params.endpoint.clone();
        let model = params.model.clone();
        let prompt = prompt.clone();
        let key = api_key.clone();
        handles.push(tokio::spawn(async move {
            let _permit = permit_src.acquire_owned().await.ok()?;
            Some(bench_once(endpoint, model, prompt, max_tokens, key).await)
        }));
    }

    let mut samples = Vec::with_capacity(total as usize);
    for h in handles {
        if let Ok(Some(s)) = h.await {
            samples.push(s);
        }
    }
    let wall_ms = wall_start.elapsed().as_secs_f64() * 1000.0;

    let ok_count = samples.iter().filter(|s| s.ok).count() as u32;
    let errors = samples.len() as u32 - ok_count;
    let total_completion: u64 = samples
        .iter()
        .filter(|s| s.ok)
        .map(|s| s.completion as u64)
        .sum();
    let ttft_series: Vec<f64> = samples.iter().filter_map(|s| s.ttft_ms).collect();
    let decode_series: Vec<f64> = samples.iter().filter_map(|s| s.decode_tok_s).collect();
    let agg_decode_tok_s = if wall_ms > 0.0 {
        total_completion as f64 / (wall_ms / 1000.0)
    } else {
        0.0
    };

    Ok(BenchResult {
        requests: total,
        ok: ok_count,
        errors,
        wall_ms,
        ttft_ms: bench_agg(&ttft_series),
        decode_tok_s: bench_agg(&decode_series),
        agg_decode_tok_s,
        total_completion_tokens: total_completion,
        ttft_series,
        decode_series,
    })
}

