/// Rebuild the active path suffix starting from `start_id` (the chosen sibling),
/// picking the newest child at each fork. The frontend splices this onto the
/// unchanged prefix before the branch point.
#[tauri::command]
pub fn walk_from(state: State<'_, AppState>, start_id: i64) -> Vec<MessageDto> {
    state
        .storage
        .lock()
        .unwrap()
        .walk_from(start_id)
        .iter()
        .map(message_to_dto)
        .collect()
}

/// Reasoning is persisted inline as a leading `<think>` block so it round-trips
/// and the frontend can collapse it on reload.
/// Flat per-image token estimate (real vision token counts are tile-based, not
/// derivable from the data-URL length; this just keeps image-heavy chats from
/// under-counting so badly that compaction never fires).
const IMAGE_TOKEN_EST: usize = 1000;

/// Coarse token estimate for the compaction trigger. ~4 chars/token matches the
/// frontend's `gpt-tokenizer` fallback; only needs to be roughly right to decide
/// *whether* to compact. Tool-call arguments and images count too, since they're
/// sent on the wire. (Could be swapped for `tiktoken-rs` or the API's reported
/// `prompt_tokens`.)
fn estimate_tokens(messages: &[Message]) -> usize {
    let mut chars = 0usize;
    for m in messages {
        for part in &m.content {
            match part {
                ContentPart::Text { text } => chars += text.len(),
                ContentPart::ImageUrl { .. } => chars += IMAGE_TOKEN_EST * 4,
            }
        }
        if let Some(calls) = &m.tool_calls {
            for c in calls {
                chars += c.function.name.len() + c.function.arguments.len();
            }
        }
    }
    chars / 4
}

/// Index of the first "live" (un-summarized) message: just past the persisted
/// compaction boundary, or 0 when there's no boundary on the current branch
/// (e.g. after navigating to a sibling that diverged before the boundary).
fn live_start(messages: &[Message], summary_through: Option<i64>) -> usize {
    summary_through
        .and_then(|t| messages.iter().position(|m| m.id == Some(t)).map(|i| i + 1))
        .unwrap_or(0)
}

const DEFAULT_COMPACT_PROMPT: &str = "You are a context-compaction engine. Produce a \
dense, factual summary of the conversation so far so it can replace the original \
messages while preserving everything needed to continue. Capture: the user's goals and \
constraints, key decisions and their rationale, important facts/values/file paths/code \
identifiers, the state of any ongoing task, and unresolved questions or next steps. \
Preserve specifics over generalities. Do not add commentary, greetings, or meta text — \
output only the summary.";

/// Make a side LLM call to summarize `to_summarize` (optionally continuing a prior
/// `existing_summary`) into a single compact string. Reuses the streaming path and
/// drains it; returns `None` on error/empty so the caller can skip compaction.
async fn summarize(
    gp: &GenParams,
    api_key: Option<String>,
    custom_prompt: &str,
    existing_summary: Option<&str>,
    to_summarize: &[Message],
    cancel: CancellationToken,
) -> Option<String> {
    let system = if custom_prompt.trim().is_empty() {
        DEFAULT_COMPACT_PROMPT
    } else {
        custom_prompt
    };

    let mut transcript = String::new();
    if let Some(prev) = existing_summary {
        if !prev.trim().is_empty() {
            transcript.push_str("Summary of the conversation before this point:\n");
            transcript.push_str(prev);
            transcript.push_str("\n\n");
        }
    }
    transcript.push_str("Messages to fold into the summary:\n");
    for m in to_summarize {
        let role = role_str(&m.role);
        let body = m.text_str();
        if !body.trim().is_empty() {
            transcript.push_str(&format!("\n[{role}] {body}"));
        }
        if let Some(calls) = &m.tool_calls {
            for c in calls {
                transcript.push_str(&format!(
                    "\n[{role}] (tool call {}: {})",
                    c.function.name, c.function.arguments
                ));
            }
        }
    }

    let wire = vec![
        Message::text(Role::System, system.to_string()),
        Message::text(Role::User, transcript),
    ];

    let (tx, mut rx) = mpsc::unbounded_channel::<StreamEvent>();
    let chat_params = ChatParams {
        base_url: gp.endpoint.clone(),
        model: gp.model.clone(),
        messages: wire,
        // Deterministic, no tools. Cap the summary so it stays compact and can't
        // grow unbounded across repeated compactions.
        temperature: Some(0.2),
        max_tokens: Some(2048),
        top_p: None,
        frequency_penalty: None,
        presence_penalty: None,
        stop_sequences: None,
        api_key,
        tools: None,
    };
    api::stream_chat(chat_params, tx, cancel);

    let mut out = String::new();
    let mut errored = false;
    while let Some(ev) = rx.recv().await {
        match ev {
            StreamEvent::Token(t) => out.push_str(&t),
            StreamEvent::Error(_) => errored = true,
            StreamEvent::Done => break,
            _ => {}
        }
    }

    let out = out.trim().to_string();
    if errored || out.is_empty() {
        None
    } else {
        Some(out)
    }
}

fn combine_stored(reasoning: &str, content: &str) -> String {
    if reasoning.is_empty() {
        content.to_string()
    } else {
        format!("<think>{reasoning}</think>\n{content}")
    }
}

struct StreamOutcome {
    content: String,
    reasoning: String,
    tool_calls: Vec<ToolCall>,
    errored: bool,
    prompt_tokens: Option<u32>,
    completion_tokens: Option<u32>,
    ttft_ms: Option<f64>,
    decode_tok_s: Option<f64>,
    cost: Option<f64>,
}

/// Run one streaming completion, forwarding tokens/reasoning/usage/metrics to
/// the frontend and returning the assembled result for the orchestration loop.
async fn stream_once(
    gp: &GenParams,
    wire: Vec<Message>,
    api_key: Option<String>,
    tools: Option<Vec<serde_json::Value>>,
    cancel: CancellationToken,
    on_event: &Channel<ChatEvent>,
) -> StreamOutcome {
    let (tx, mut rx) = mpsc::unbounded_channel::<StreamEvent>();
    let chat_params = ChatParams {
        base_url: gp.endpoint.clone(),
        model: gp.model.clone(),
        messages: wire,
        temperature: gp.temperature,
        max_tokens: if gp.use_max_tokens {
            gp.max_tokens
        } else {
            None
        },
        top_p: gp.top_p,
        frequency_penalty: gp.frequency_penalty,
        presence_penalty: gp.presence_penalty,
        stop_sequences: if gp.stop_sequences.is_empty() {
            None
        } else {
            Some(gp.stop_sequences.clone())
        },
        api_key,
        tools,
    };
    api::stream_chat(chat_params, tx, cancel);

    let start = Instant::now();
    let mut first_token_at: Option<Instant> = None;
    let mut content = String::new();
    let mut reasoning = String::new();
    let mut tool_calls: Vec<ToolCall> = Vec::new();
    let mut usage_prompt: Option<u32> = None;
    let mut usage_completion: Option<u32> = None;
    let mut usage_cost: Option<f64> = None;
    let mut errored = false;

    while let Some(ev) = rx.recv().await {
        match ev {
            StreamEvent::Token(t) => {
                first_token_at.get_or_insert_with(Instant::now);
                content.push_str(&t);
                on_event.send(ChatEvent::Token { text: t }).ok();
            }
            StreamEvent::Reasoning(r) => {
                first_token_at.get_or_insert_with(Instant::now);
                reasoning.push_str(&r);
                on_event.send(ChatEvent::Reasoning { text: r }).ok();
            }
            StreamEvent::ToolCalls(calls) => {
                tool_calls = calls;
            }
            StreamEvent::UsageInfo(u) => {
                usage_prompt = u.prompt_tokens;
                usage_completion = u.completion_tokens;
                usage_cost = u.cost;
                on_event
                    .send(ChatEvent::Usage {
                        prompt_tokens: u.prompt_tokens,
                        completion_tokens: u.completion_tokens,
                        total_tokens: u.total_tokens,
                        cost: u.cost,
                    })
                    .ok();
            }
            StreamEvent::Error(msg) => {
                errored = true;
                on_event.send(ChatEvent::Error { message: msg }).ok();
            }
            StreamEvent::Done => break,
            StreamEvent::ModelsLoaded { .. } => {}
        }
    }

    let now = Instant::now();
    let duration_ms = now.duration_since(start).as_secs_f64() * 1000.0;
    let ttft_ms = first_token_at.map(|t| t.duration_since(start).as_secs_f64() * 1000.0);
    let decode_tok_s = match (usage_completion, first_token_at) {
        (Some(ct), Some(ft)) if ct > 0 => {
            let decode_s = now.duration_since(ft).as_secs_f64();
            (decode_s > 0.0).then(|| ct as f64 / decode_s)
        }
        _ => None,
    };
    let prefill_tok_s = match (usage_prompt, ttft_ms) {
        (Some(pt), Some(ttft)) if ttft > 0.0 => Some(pt as f64 / (ttft / 1000.0)),
        _ => None,
    };
    on_event
        .send(ChatEvent::RequestMetrics {
            ttft_ms,
            decode_tok_s,
            prefill_tok_s,
            duration_ms,
        })
        .ok();

    StreamOutcome {
        content,
        reasoning,
        tool_calls,
        errored,
        prompt_tokens: usage_prompt,
        completion_tokens: usage_completion,
        ttft_ms,
        decode_tok_s,
        cost: usage_cost,
    }
}

/// Park a oneshot keyed by the tool_call id and emit a `tool_approval` event;
/// resolves when `resolve_tool` fires or the stream is cancelled (→ denied).
async fn request_approval(
    state: &State<'_, AppState>,
    on_event: &Channel<ChatEvent>,
    call: &ToolCall,
    conversation_id: i64,
    cancel: &CancellationToken,
) -> bool {
    let (tx, rx) = oneshot::channel::<bool>();
    state.pending_approvals.lock().unwrap().insert(
        call.id.clone(),
        crate::state::PendingApproval {
            tx,
            conversation_id,
            tool: call.function.name.clone(),
        },
    );
    on_event
        .send(ChatEvent::ToolApproval {
            id: call.id.clone(),
            name: call.function.name.clone(),
            arguments: call.function.arguments.clone(),
        })
        .ok();
    tokio::select! {
        r = rx => r.unwrap_or(false),
        _ = cancel.cancelled() => {
            state.pending_approvals.lock().unwrap().remove(&call.id);
            false
        }
    }
}

/// Dispatch a tool call to its handler on a blocking thread (builtins and
/// shell tools are synchronous and can run for a while). Returns
/// `(output, is_error)`.
async fn execute_tool(def: ToolDef, call: &ToolCall, wd: PathBuf) -> (String, bool) {
    let args: serde_json::Value =
        serde_json::from_str(&call.function.arguments).unwrap_or_else(|_| serde_json::json!({}));
    let handler = def.handler.clone();
    let res = tokio::task::spawn_blocking(move || match handler {
        Handler::Builtin(b) => tools::run_builtin(&b.0, &args, &wd),
        Handler::Shell { shell } => tools::run_shell_tool(&shell, &args, &wd),
    })
    .await;
    match res {
        Ok(Ok(out)) => (out, false),
        Ok(Err(e)) => (e, true),
        Err(e) => (format!("tool task failed: {e}"), true),
    }
}

/// Generate a short title from the first exchange, once, in the background.
async fn maybe_auto_title(
    state: &State<'_, AppState>,
    conversation_id: i64,
    gp: &GenParams,
    user_text: &str,
) {
    let needs = {
        let storage = state.storage.lock().unwrap();
        storage.needs_auto_title(conversation_id)
    };
    if !needs {
        return;
    }
    let api_key = state.api_key_for(&gp.endpoint);
    let prompt = vec![
        Message::text(
            Role::System,
            "Give a concise 3-6 word title for this conversation. Reply with only the title, no quotes."
                .to_string(),
        ),
        Message::text(Role::User, user_text.to_string()),
    ];
    let title = api::complete_once(
        &gp.endpoint,
        &gp.model,
        &prompt,
        api_key.as_deref(),
        // Reasoning models (e.g. nemotron) spend tokens inside a <think> block
        // before emitting the title; a tight cap leaves the block unclosed and
        // strip_reasoning yields an empty string. Give them room to finish.
        Some(512),
        Some(0.3),
    )
    .await;
    if let Ok(raw) = title {
        let clean = crate::markdown::strip_reasoning(&raw);
        let clean = clean.trim().trim_matches('"').trim();
        if !clean.is_empty() {
            let storage = state.storage.lock().unwrap();
            storage.update_conversation_title(conversation_id, clean);
            storage.mark_auto_titled(conversation_id);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn with_id(mut m: Message, id: i64) -> Message {
        m.id = Some(id);
        m
    }

    #[test]
    fn live_start_finds_boundary_or_zero() {
        let msgs = vec![
            with_id(Message::text(Role::User, "a".into()), 1),
            with_id(Message::text(Role::Assistant, "b".into()), 2),
            with_id(Message::text(Role::User, "c".into()), 3),
            with_id(Message::text(Role::Assistant, "d".into()), 4),
        ];
        assert_eq!(live_start(&msgs, None), 0);
        assert_eq!(live_start(&msgs, Some(2)), 2);
        assert_eq!(live_start(&msgs, Some(4)), 4);
        // Boundary id not on this branch → treat as un-compacted (full history).
        assert_eq!(live_start(&msgs, Some(999)), 0);
    }

    #[test]
    fn estimate_tokens_counts_text_and_images() {
        let text = Message::text(Role::User, "x".repeat(40)); // 40 chars → ~10 tokens
        let image = Message {
            role: Role::User,
            content: vec![ContentPart::ImageUrl {
                image_url: ImageUrl {
                    url: "data:image/png;base64,AAAA".into(),
                    detail: None,
                },
            }],
            tool_calls: None,
            tool_call_id: None,
            created_at: None,
            id: None,
            parent_id: None,
            branch_index: 0,
        };
        // Images must contribute (text_str() alone would count them as 0).
        assert_eq!(estimate_tokens(std::slice::from_ref(&text)), 10);
        assert!(estimate_tokens(&[text, image]) >= IMAGE_TOKEN_EST + 10);
    }
}

