//! Usage statistics and benchmark commands: stats, clear, benchmark.

use crate::api::{self, ChatParams, StreamEvent};
use crate::commands::{BenchParams, BenchResult, UsageStatsDto};
use crate::state::AppState;
use serde::{Deserialize, Serialize};
use std::sync::Arc;
