fn settings_from_gen(gp: &crate::modules::dto::GenParams, working_dir: Option<String>) -> ConversationSettings {
    ConversationSettings {
        model: Some(gp.model.clone()),
        system_prompt: Some(gp.system_prompt.clone()),
