}

/// avg / p50 / p95 of a metric across the benchmark's successful requests.
#[derive(Serialize, Default)]
pub struct BenchAgg {
    pub avg: Option<f64>,
    pub p50: Option<f64>,
    pub p95: Option<f64>,
}

#[derive(Serialize)]
pub struct BenchResult {
    pub requests: u32,
    pub ok: u32,

