/// Generate a short title from the first exchange, once, in the background.
async fn maybe_auto_title(
    state: &State<'_, AppState>,
    conversation_id: i64,
    gp: &GenParams,
    user_text: &str,
) {
    let needs = {
        let storage = state.storage.lock().unwrap();
        storage.needs_auto_title(conversation_id)
    };
    if !needs {
        return;
    }
    let api_key = state.api_key_for(&gp.endpoint);
    let prompt = vec![
        Message::text(
            Role::System,
            "Give a concise 3-6 word title for this conversation. Reply with only the title, no quotes."
                .to_string(),
        ),
        Message::text(Role::User, user_text.to_string()),
    ];
    let title = api::complete_once(
        &gp.endpoint,
        &gp.model,
        &prompt,
        api_key.as_deref(),
        // Reasoning models (e.g. nemotron) spend tokens inside a <think> block
        // before emitting the title; a tight cap leaves the block unclosed and
        // strip_reasoning yields an empty string. Give them room to finish.
        Some(512),
        Some(0.3),
    )
    .await;
    if let Ok(raw) = title {
        let clean = crate::markdown::strip_reasoning(&raw);
        let clean = clean.trim().trim_matches('"').trim();
        if !clean.is_empty() {
            let storage = state.storage.lock().unwrap();
            storage.update_conversation_title(conversation_id, clean);
            storage.mark_auto_titled(conversation_id);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn with_id(mut m: Message, id: i64) -> Message {
        m.id = Some(id);
        m
    }

    #[test]
    fn live_start_finds_boundary_or_zero() {
        let msgs = vec![
            with_id(Message::text(Role::User, "a".into()), 1),
            with_id(Message::text(Role::Assistant, "b".into()), 2),
            with_id(Message::text(Role::User, "c".into()), 3),
            with_id(Message::text(Role::Assistant, "d".into()), 4),
        ];
        assert_eq!(live_start(&msgs, None), 0);
        assert_eq!(live_start(&msgs, Some(2)), 2);
        assert_eq!(live_start(&msgs, Some(4)), 4);
        // Boundary id not on this branch → treat as un-compacted (full history).
        assert_eq!(live_start(&msgs, Some(999)), 0);
    }

    #[test]
    fn estimate_tokens_counts_text_and_images() {
        let text = Message::text(Role::User, "x".repeat(40)); // 40 chars → ~10 tokens
        let image = Message {
            role: Role::User,
            content: vec![ContentPart::ImageUrl {
                image_url: ImageUrl {
                    url: "data:image/png;base64,AAAA".into(),
                    detail: None,
                },
            }],
            tool_calls: None,
            tool_call_id: None,
            created_at: None,
            id: None,
            parent_id: None,
            branch_index: 0,
        };
        // Images must contribute (text_str() alone would count them as 0).
        assert_eq!(estimate_tokens(std::slice::from_ref(&text)), 10);
        assert!(estimate_tokens(&[text, image]) >= IMAGE_TOKEN_EST + 10);
    }
}

