use tokio_util::sync::CancellationToken;

/// Max tool-call → re-stream cycles per user turn (matches the egui app).
const MAX_TOOL_ITERATIONS: usize = 8;

// ---------- DTOs ----------

#[derive(Serialize)]
pub struct ConversationDto {
