#[derive(Serialize, Clone)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ChatEvent {
    Started { conversation_id: i64 },
    TurnStart,
    Token { text: String },
    Reasoning { text: String },
    ToolCall {
        id: String,
        name: String,
        arguments: String,
    },
    ToolApproval {
        id: String,
        name: String,
        arguments: String,
    },
    ToolResult {
        id: String,
