        is_error: bool,
    },
    Usage {
        prompt_tokens: Option<u32>,
        completion_tokens: Option<u32>,
        total_tokens: Option<u32>,
        cost: Option<f64>,
    },
    RequestMetrics {
        ttft_ms: Option<f64>,
        decode_tok_s: Option<f64>,
        prefill_tok_s: Option<f64>,
        duration_ms: f64,
    },
    Done { message_id: Option<i64> },
    Error { message: String },
    Compacted {
        through_id: i64,
        summary: String,
        removed: usize,
    },
}

// ---------- Config Commands ----------

use crate::helpers::config::{get_config_helper, save_config_helper, api_key_for_helper, fetch_models_helper};
use crate::helpers::project::{list_projects_helper, create_project_helper, rename_project_helper, delete_project_helper, set_project_pinned_helper, set_conversation_project_helper};
use crate::helpers::usage::{usage_stats_helper, clear_usage_helper, run_benchmark_helper};
use crate::helpers::system::{delete_conversation_helper, delete_all_conversations_helper, rename_conversation_helper, set_pinned_helper, search_conversations_helper, export_conversation_helper, export_conversation_file_helper, list_presets_helper, create_preset_helper, delete_preset_helper};
use crate::helpers::mcp::{get_mcp_status_helper, list_mcp_servers_helper, reconnect_mcp_helper};
use crate::helpers::chat::{run_streaming, maybe_auto_title, settings_from_gen, resolve_wd, message_to_dto};

#[tauri::command]
pub async fn get_config(state: State<'_, AppState>) -> Result<crate::config::Config, String> {
    get_config_helper(&state)
}

#[tauri::command]
pub async fn save_config(state: State<'_, AppState>, config: crate::config::Config) -> Result<(), String> {
    save_config_helper(&state, config)
}

#[tauri::command]
pub async fn fetch_models(state: State<'_, AppState>) -> Result<Vec<String>, String> {
    fetch_models_helper(&state).await
}

// ---------- Conversation Commands ----------

#[tauri::command]
pub async fn list_conversations(state: State<'_, AppState>) -> Result<Vec<ConversationDto>, String> {
    let storage = state.storage.lock().unwrap();
    Ok(storage.list_conversations())
}

#[tauri::command]
pub async fn load_conversation(state: State<'_, AppState>, id: i64) -> Result<ConversationData, String> {
    let storage = state.storage.lock().unwrap();
    let (messages, settings, draft, summary, summary_through) = storage.load_conversation(id);
    let messages = messages.iter().map(message_to_dto).collect();
    let settings = SettingsDto {
        model: settings.model.clone(),
        endpoint: settings.endpoint.clone(),
        system_prompt: settings.system_prompt.clone(),
        temperature: settings.temperature.unwrap_or(1.0),
        max_tokens: settings.max_tokens.unwrap_or(1024),
        use_max_tokens: settings.use_max_tokens.unwrap_or(false),
        top_p: settings.top_p,
        frequency_penalty: settings.frequency_penalty,
        presence_penalty: settings.presence_penalty,
        stop_sequences: settings.stop_sequences.clone(),
        working_dir: settings.working_dir.clone(),
        auto_compact: settings.auto_compact.unwrap_or(true),
        compact_threshold_pct: settings.compact_threshold_pct.unwrap_or(80.0),
        compact_keep_recent: settings.compact_keep_recent.unwrap_or(20),
    };
    Ok(ConversationData {
        messages,
        settings,
        draft,
        summary,
        summary_through,
    })
}

