// ---------- Streaming Commands ----------

#[tauri::command]
pub async fn send_message(
    state: State<'_, AppState>,
    params: SendParams,
    on_event: Channel<ChatEvent>,
) -> Result<i64, String> {
    run_streaming(
        &state,
        params.conversation_id.unwrap_or(0),
        vec![],
        &params.gp,
        None,
        resolve_wd(params.gp.working_dir),
        0,
        &on_event,
    )
    .await
    .0
    .ok_or_else(|| "Failed to send message".to_string())
}

#[tauri::command]
pub async fn regenerate(
    state: State<'_, AppState>,
    params: RegenerateParams,
    on_event: Channel<ChatEvent>,
) -> Result<i64, String> {
    let storage = state.storage.lock().unwrap();
    let messages = storage.load_conversation(params.conversation_id).0;

    run_streaming(
        &state,
        params.conversation_id,
        messages,
        &params.gp,
        None,
        resolve_wd(params.gp.working_dir),
        0,
        &on_event,
    )
    .await
    .0
    .ok_or_else(|| "Failed to regenerate message".to_string())
}

#[tauri::command]
pub async fn edit_message(
    state: State<'_, AppState>,
    params: EditParams,
    on_event: Channel<ChatEvent>,
) -> Result<i64, String> {
    let storage = state.storage.lock().unwrap();
    let mut messages = storage.load_conversation(params.conversation_id).0;

    let mut assistant_message = None;
    for msg in &mut messages {
        if msg.id == Some(params.message_id) && matches!(msg.role, Role::Assistant) {
            assistant_message = Some(msg);
            break;
        }
    }

    if let Some(assistant) = assistant_message {
        assistant.text = params.new_text;
    } else {
        return Err("Message not found or not editable".to_string());
    }

    run_streaming(
        &state,
        params.conversation_id,
        messages,
        &params.gp,
        None,
        resolve_wd(params.gp.working_dir),
        0,
        &on_event,
    )
    .await
    .0
    .ok_or_else(|| "Failed to edit message".to_string())
}

#[tauri::command]
pub async fn message_siblings(state: State<'_, AppState>, conversation_id: i64, message_id: i64) -> Result<Vec<MessageDto>, String> {
    let storage = state.storage.lock().unwrap();
    let messages = storage.load_conversation(conversation_id).0;

    let mut siblings = Vec::new();
    for msg in &messages {
        if msg.id == Some(message_id) || msg.parent_id == Some(message_id) {
            siblings.push(message_to_dto(msg));
        }
    }

    Ok(siblings)
}

#[tauri::command]
pub async fn walk_from(state: State<'_, AppState>, conversation_id: i64, message_id: i64) -> Result<Vec<MessageDto>, String> {
    let storage = state.storage.lock().unwrap();
    let messages = storage.load_conversation(conversation_id).0;

    let mut result = Vec::new();
    let mut found = false;

    for msg in &messages {
        if found {
            result.push(message_to_dto(msg));
        } else if msg.id == Some(message_id) {
            found = true;
        }
    }

    Ok(result)
}

#[tauri::command]
pub async fn cancel_stream(state: State<'_, AppState>, conversation_id: i64) -> Result<(), String> {
    let mut cancel_tokens = state.cancel.lock().unwrap();
    if let Some(token) = cancel_tokens.remove(&conversation_id) {
        token.cancel();
    }
    Ok(())
}

#[tauri::command]
pub async fn resolve_tool(state: State<'_, AppState>, call_id: String, approved: bool) -> Result<(), String> {
    let mut pending = state.pending_approvals.lock().unwrap();
    if let Some(approval) = pending.remove(&call_id) {
        if approved {
            approval.tx.send(true).ok();
        } else {
            approval.tx.send(false).ok();
        }
    }
    Ok(())
}

#[tauri::command]
pub async fn save_draft(state: State<'_, AppState>, conversation_id: i64, draft: String) -> Result<(), String> {
    let mut storage = state.storage.lock().unwrap();
    storage.save_draft(conversation_id, draft);
    Ok(())
}

#[tauri::command]
pub async fn list_agents(state: State<'_, AppState>) -> Result<Vec<String>, String> {
    let agents = crate::agents::list();
    Ok(agents)
}

#[tauri::command]
pub async fn list_mcp_servers(state: State<'_, AppState>) -> Result<Vec<crate::commands::McpServer>, String> {
    list_mcp_servers_helper(&state)
}

#[tauri::command]
pub async fn reconnect_mcp(state: State<'_, AppState>) -> Result<(), String> {
    reconnect_mcp_helper(&state).await
}

#[tauri::command]
pub async fn set_metrics_target(state: State<'_, AppState>, target: String) -> Result<(), String> {
    let mut metrics_handle = state.metrics_handle.lock().unwrap();
    metrics_handle.set_target(target);
    Ok(())
}

