    #[default]
    None,
    /// Local Apple Silicon GPU via the macmon sampler (no sudo).
    Macmon,
    /// A remote `fornax-agent` exposing nvidia-smi + /proc/meminfo over HTTP.
    Agent,
}

fn runtime_is_default(r: &Runtime) -> bool {
    *r == Runtime::Openai
}
fn gpu_is_default(g: &GpuKind) -> bool {
    *g == GpuKind::None
}

