//! Tauri command layer for Fornax

use crate::state::AppState;
use serde::{Deserialize, Serialize};
use tauri::State;

// ---------- Config Commands ----------

#[tauri::command]
pub async fn get_config(state: State<'_, AppState>) -> Result<crate::config::Config, String> {
    let config = state.config.lock().unwrap();
    Ok(config.clone())
}

#[tauri::command]
pub async fn save_config(state: State<'_, AppState>, config: crate::config::Config) -> Result<(), String> {
    let mut state_config = state.config.lock().unwrap();
    *state_config = config;
    Ok(())
}

#[tauri::command]
pub async fn fetch_models(state: State<'_, AppState>) -> Result<Vec<crate::api::ModelInfo>, String> {
    let config = state.config.lock().unwrap();
    let api_key = config.saved_endpoints.iter().find(|ep| ep.url == config.default_endpoint).and_then(|ep| ep.api_key.clone());
    let models = crate::api::fetch_models(
        &config.default_endpoint,
        api_key.as_deref(),
    )
    .await
    .map_err(|e| e.to_string())?;
    Ok(models)
}

// ---------- Conversation Commands ----------

#[tauri::command]
pub async fn list_conversations(state: State<'_, AppState>) -> Result<Vec<crate::commands::ConversationDto>, String> {
    let storage = state.storage.lock().unwrap();
    let conversations = storage.list_conversations();
    let conversations: Vec<crate::commands::ConversationDto> = conversations
        .into_iter()
        .map(|c| crate::commands::ConversationDto {
            id: c.id,
            title: c.title,
            pinned: c.pinned,
            project_id: c.project_id,
            runtime: c.endpoint, // Map endpoint to runtime field
        })
        .collect();
    Ok(conversations)
}

#[tauri::command]
pub async fn load_conversation(state: State<'_, AppState>, id: i64) -> Result<crate::commands::ConversationData, String> {
    let storage = state.storage.lock().unwrap();
    let messages = storage.load_messages(id);
    let settings = storage.load_conversation_settings(id);
    let draft = storage.load_draft(id);
    let summary = storage.load_summary(id);
    let summary_through = storage.load_summary_through(id);

    let messages_dto: Vec<crate::commands::MessageDto> = messages
        .into_iter()
        .map(|m| {
            let images: Vec<String> = m.content
                .iter()
                .filter_map(|p| match p {
                    crate::message::ContentPart::ImageUrl { image_url } => Some(image_url.url.clone()),
                    _ => None,
                })
                .collect();
            let tool_calls = m.tool_calls.as_ref().map(|calls| {
                calls
                    .iter()
                    .map(|c| crate::commands::ToolCallDto {
                        id: c.id.clone(),
                        name: c.function.name.clone(),
                        arguments: c.function.arguments.clone(),
                    })
                    .collect()
            });
            crate::commands::MessageDto {
                id: m.id,
                role: match m.role {
                    crate::message::Role::System => "system",
                    crate::message::Role::User => "user",
                    crate::message::Role::Assistant => "assistant",
                    crate::message::Role::Tool => "tool",
                }
                .to_string(),
                text: m.text_str(),
                images,
                tool_calls,
                tool_call_id: m.tool_call_id.clone(),
                created_at: m.created_at,
            }
        })
        .collect();

    let settings_dto = crate::commands::SettingsDto {
        model: settings.model.clone(),
        endpoint: settings.endpoint.clone(),
        system_prompt: settings.system_prompt.clone(),
        temperature: settings.temperature.unwrap_or(1.0),
        max_tokens: settings.max_tokens.unwrap_or(1024),
        use_max_tokens: settings.use_max_tokens.unwrap_or(false),
        top_p: settings.top_p,
        frequency_penalty: settings.frequency_penalty,
        presence_penalty: settings.presence_penalty,
        stop_sequences: settings.stop_sequences.clone(),
        working_dir: settings.working_dir.clone(),
        auto_compact: settings.auto_compact.unwrap_or(true),
        compact_threshold_pct: settings.compact_threshold_pct.unwrap_or(80.0),
        compact_keep_recent: settings.compact_keep_recent.unwrap_or(20),
    };

    Ok(crate::commands::ConversationData {
        messages: messages_dto,
        settings: settings_dto,
        draft,
        summary,
        summary_through,
    })
}

#[tauri::command]
